import pandas as pd

def solve(data):
     orders = pd.DataFrame({'id':data['orders']})
     catalog = pd.DataFrame({'id':data['catalog']})
     try:
         joined = orders.merge(catalog, on='id', how='left', validate='many_to_one', indicator=True)
     except pd.errors.MergeError:
         return {'valid':False, 'missing':[]}
     return {'valid':True, 'missing':joined.loc[joined['_merge'] == 'left_only','id'].tolist()}
